<script setup>
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {ElMessage,ElMessageBox} from 'element-plus';
import AiProductImportDialog from '../../components/listing/AiProductImportDialog.vue';
import {apiClient,currentApiCacheScope} from '../../utils/api.js';
import {normalizeImportVariants,normalizeImportCandidate} from '../../utils/ai-product-import.js';
import {uploadListingMedia,withImageToken} from '../../api/tools/imageCropper.js';
import {generateAiCommerceCopy,generateAiImages} from '../../api/tools/aiImageGenerator.js';
const route=useRoute(),router=useRouter(),importer=ref(null),sources=ref([]),listingTemplates=ref([]),selected=ref(0),record=ref(null),busy=ref(''),error=ref(''),analysis=ref(null),manualAnalysis=ref(''),plan=ref(null),planCount=ref(3),planDirection=ref(''),planConfirmed=ref(false),draftId=ref('');
const fields=ref([]),promptTemplates=ref([]);let disposed=false,actionSequence=0;
const active=computed(()=>sources.value[selected.value]);
const hasResults=computed(()=>fields.value.some(f=>f.adopted));
const categories={title:'title',tags:'tags',description:'description',main:'main',detail:'detail'};
function slot(key,label,value,kind='text'){return {key,label,kind,original:value||'',value:value||'',prompt:'',reference:'',result:'',adopted:false};}
function initialize(){const s=active.value;if(!s)return;fields.value=[slot('title','标题',s.title),slot('tags','标签',Array.isArray(s.tags)?s.tags.join(' '):s.tags),slot('description','描述',s.description),slot('main','主图',s.imageUrl,'image'),...(s.detailImages||[]).map((url,i)=>slot('detail_'+i,'详情图 '+(i+1),url,'image'))];record.value=null;analysis.value=null;manualAnalysis.value='';plan.value=null;draftId.value='';error.value='';planConfirmed.value=false;}
async function importSource(candidate){if(busy.value)return;if(hasResults.value){try{await ElMessageBox.confirm('当前采用结果已保存在生成记录中。导入另一套内容？','切换商品');}catch{return;}}sources.value=normalizeImportVariants(candidate);selected.value=0;initialize();listingTemplates.value=await apiClient.get('/api/listing/templates',{noCache:true}).catch(()=>[]);}
async function chooseSource(index){if(busy.value||index===selected.value)return;if(hasResults.value){try{await ElMessageBox.confirm('当前结果可从生成记录恢复，切换到其他变体？','切换变体');}catch{return;}}selected.value=index;initialize();}
async function bindTemplate(id){await work('template',async check=>{const template=await apiClient.get('/api/listing/templates/'+encodeURIComponent(id)+'?mode=editor',{noCache:true});check();active.value.templateId=id;active.value.templatePayload=template;await persist();});}
function snapshot(){return {name:active.value?.title||'AI优化',sourceModule:'ai_optimizer',source:active.value,fields:JSON.parse(JSON.stringify(fields.value)),analysis:analysis.value,manualAnalysis:manualAnalysis.value,plan:plan.value,draftId:draftId.value};}
async function persist(){const scope=currentApiCacheScope(),seq=actionSequence;const saved=await apiClient.post('/api/product-workflows/optimizations',{...(record.value?{id:record.value.id,revision:record.value.revision}:{}),payload:snapshot()});if(disposed||scope!==currentApiCacheScope()||seq!==actionSequence)throw Error('企业或页面已变化，请重新打开记录');record.value=saved;}
async function work(key,fn){if(busy.value)return;busy.value=key;error.value='';const scope=currentApiCacheScope(),seq=++actionSequence;const check=()=>{if(disposed||scope!==currentApiCacheScope()||seq!==actionSequence)throw Error('企业或页面已变化，结果请到生成记录查看');};try{await fn(check);}catch(e){error.value=e.message||'操作失败';ElMessage.error(error.value);}finally{if(seq===actionSequence)busy.value='';}}
const candidates=()=>fields.value.filter(f=>f.kind==='image'&&f.value).map((f,i)=>({candidate_id:f.key,kind:i?'detail':'main',url:f.value,label:f.label,source:'original'}));
const context=()=>({title:fields.value[0]?.value||'',tags:fields.value[1]?.value?.split(/\s+/).filter(Boolean)||[],description:fields.value[2]?.value||'',sourceProductId:active.value?.sourceSku||'',sourceImageUrl:fields.value.find(f=>f.key==='main')?.value||'',candidates:candidates()});
function analyze(){work('analyze',async check=>{const r=await apiClient.post('/api/ai-variant-lab/optimize/analyze',{...context(),forceAnalyze:true,goal:'综合检查当前标题、标签、描述、主图和详情图。用中文逐项指出具体问题、改进方向和必须保留的真实产品事实，不编造信息。'});check();analysis.value=r.analysis||r;await persist();});}
const analysisSections=computed(()=>{const a=analysis.value||{},d=a.display_zh||{};return [{label:'产品识别',value:d.recognition_summary||d.product_type||a.product_type},{label:'当前问题',value:a.current_problems},{label:'优化建议',value:a.improvement_opportunities||d.recommended_action},{label:'必须保留',value:a.keep_facts||d.fixed_facts}].filter(s=>s.value).map(s=>({...s,value:Array.isArray(s.value)?s.value.join('\n'):typeof s.value==='object'?Object.values(s.value).join('\n'):s.value}));});
function category(f){return categories[f.key]||'detail';}
function presets(f){return promptTemplates.value.filter(p=>p.payload.category===category(f));}
async function uploadReference(event,f){const file=event.target.files?.[0];if(!file)return;await work('upload:'+f.key,async check=>{const r=await uploadListingMedia(file,{source_module:'ai_optimizer',role:'reference'});check();const url=r.publishUrl||r.url||r.previewUrl;if(!url)throw Error('上传未返回图片地址');f.reference=url;});event.target.value='';}
function optimize(f){if(!f.prompt.trim())return ElMessage.warning('请先填写这一项的优化要求');work(f.key,async check=>{let result;if(f.kind==='text'){const r=await generateAiCommerceCopy({productName:active.value.title,title:context().title,tags:context().tags,summary:context().description,productTruth:analysis.value||{},rules:['只基于已确认的产品资料，用自然俄语优化，不编造规格、适配或认证。',`本次仅优化${f.label}：${f.prompt}`,manualAnalysis.value].filter(Boolean)},{sourceModule:'ai_optimizer'});check();result=f.key==='title'?(r.titles?.[0]||r.title):f.key==='tags'?(Array.isArray(r.tags)?r.tags.join(' '):r.tags):r.description;}else{const main=fields.value.find(x=>x.key==='main')?.value;const r=await generateAiImages({sourceImageUrl:f.value||main,sourceImageUrls:[f.value||main,f.reference].filter(Boolean),ratio:'3:4',imageCount:1,autoCrop:false,finalPrompt:`保留第一张图片中产品的真实外形、材质、颜色、标识、数量和已确认适配。第二张图片如提供，仅参考构图与场景，不替换产品。禁止虚构规格或认证。买家可见文字使用俄语。\n本项要求：${f.prompt}\n已确认事实：${JSON.stringify(analysis.value?.keep_facts||[])}\n人工分析：${manualAnalysis.value}`},{sourceModule:'ai_optimizer'});check();result=imageUrl(r);}if(!result)throw Error('AI未返回这一项的有效结果');f.result=result;await persist();ElMessage.success('结果已保存，请对比后选择采用');});}
function imageUrl(r){const i=r.generatedImages?.[0]||r.croppedImages?.[0]||{};return i.publishUrl||i.publish_url||i.previewUrl||i.url||'';}
function adopt(f){work('adopt',async()=>{f.value=f.result;f.adopted=true;await persist();});}
function createPlan(){if(!analysis.value)return ElMessage.warning('请先运行一键分析，再生成套图方案');work('plan',async check=>{const r=await apiClient.post('/api/ai-variant-lab/optimize/plan',{...context(),analysis:analysis.value,operatorNote:`只制定${planCount.value}张场景详情图方案，方向：${planDirection.value||'根据真实卖点制定不同使用场景'}。先给方案，不生成图片。`,goal:'基于主图和真实卖点制定场景图方案，每张图说明用途、构图和必须呈现的事实。'});check();const shots=r.plan?.suite_storyboard||[];const list=(Array.isArray(shots)?shots:(shots.shots||shots.details||[])).filter(s=>s.role!=='main');if(list.length<Number(planCount.value))throw Error(`本次只返回${list.length}个场景方案，请减少数量或重试，尚未生成图片`);plan.value=list.slice(0,Number(planCount.value)).map((s,i)=>({id:crypto.randomUUID(),name:`场景图 ${i+1} · ${s.objective_zh||s.objective||s.role||'真实使用场景'}`,prompt:[s.composition_en||s.composition,s.must_show_en||s.must_show].filter(Boolean).join('\n')||JSON.stringify(s),result:'',error:''}));planConfirmed.value=false;await persist();});}
watch([planCount,planDirection],()=>{planConfirmed.value=false;});
function generateScenes(){if(!planConfirmed.value||!plan.value?.length||plan.value.length!==Number(planCount.value))return ElMessage.warning('请先确认场景方案与数量');work('scenes',async check=>{const main=fields.value.find(f=>f.key==='main')?.value;for(const scene of plan.value){if(scene.result)continue;try{const r=await generateAiImages({sourceImageUrl:main,ratio:'3:4',imageCount:1,autoCrop:false,finalPrompt:`以主图中真实产品为核心，保持产品不变，生成与主图风格一致的场景详情图。只使用已确认事实，不编造规格或配件，买家可见文字用俄语。\n${scene.name}\n${scene.prompt}`},{sourceModule:'ai_optimizer'});check();scene.result=imageUrl(r);if(!scene.result)throw Error('未返回图片');scene.error='';}catch(e){scene.error=e.message;}check();await persist();}ElMessage.success('本次场景图生成已结束，可逐张采用或重试失败项');});}
function adoptScene(scene){work('adopt',async()=>{const key='scene_'+scene.id;if(!fields.value.some(f=>f.key===key))fields.value.push({...slot(key,scene.name,scene.result,'image'),adopted:true});await persist();});}
async function saveDraft(){work('draft',async check=>{const source=active.value;if(!source?.templateId)throw Error('请先选择本企业的上架模板，再保存新草稿；没有模板时请先到草稿箱配置类目');if(!hasResults.value)throw Error('请先采用需要保存的优化结果');await persist();check();const images=fields.value.filter(f=>f.kind==='image'&&f.value).map(f=>f.value);const offer=await apiClient.post('/api/listing/generate-offer-id',{prefix:'OPT',existingIds:[]});check();const offerId=offer.offerId||offer.offer_id;if(!offerId)throw Error('未生成商品编号');const result=await apiClient.post('/api/listing/drafts/ai-variant-lightweight',{template_id:source.templateId,template_payload:source.templatePayload,source_draft_id:source.sourceDraftId||'',source_variant_key:source.sourceVariantKey||'',source_variant_index:source.sourceVariantIndex||0,clone_source_draft:true,development_type:'copy',shop_ids:source.sourceShopIds||[],product_name:fields.value[0].value,offer_id:offerId,internal_code:offerId,source_images:images,patch:{offer_id:offerId,title:fields.value[0].value,tags:fields.value[1].value.split(/\s+/).filter(Boolean),description:fields.value[2].value,images},manual_facts:{source_product_id:source.sourceSku,optimization_record_id:record.value.id},changed_fields:['offer_id','title','tags','description','images']});check();draftId.value=result.id||result.draft_id;await persist();ElMessage.success('已另存为新草稿，原稿未覆盖');});}
async function importRoute(){
  if(String(route.query.autoImport||'')!=='1')return;
  const source=route.query.source==='listing_draft'?'draft':route.query.source==='collector_box'?'collector':null;
  if(!source)throw Error('AI优化仅支持草稿箱或采集箱，请通过上方按钮导入');
  const raw=source==='draft'?(route.query.draftIds||route.query.draftId):(route.query.collectorSku||route.query.sourceId);
  const ids=[...new Set(String(raw||'').split(',').filter(Boolean))].slice(0,20);const imported=[];
  for(const id of ids){const data=await apiClient.get(source==='draft'?'/api/listing/drafts/'+encodeURIComponent(id):'/api/listing/collector-box/'+encodeURIComponent(id),{noCache:true});const item=normalizeImportCandidate(data,source);imported.push(...normalizeImportVariants(item));}
  sources.value=imported;selected.value=0;initialize();
}
async function restore(id){const doc=await apiClient.get('/api/product-workflows/optimizations?id='+encodeURIComponent(id),{noCache:true});record.value=doc;sources.value=[doc.payload.source];selected.value=0;fields.value=doc.payload.fields||[];analysis.value=doc.payload.analysis;manualAnalysis.value=doc.payload.manualAnalysis||'';plan.value=doc.payload.plan;draftId.value=doc.payload.draftId||'';}
watch(()=>route.query.recordId,id=>{if(id)work('restore',()=>restore(String(id)));});
function resetScope(){actionSequence++;sources.value=[];fields.value=[];record.value=null;promptTemplates.value=[];busy.value='';}
onMounted(async()=>{window.addEventListener('erp:auth-scope-changed',resetScope);try{promptTemplates.value=await apiClient.get('/api/product-workflows/prompts',{noCache:true});if(route.query.recordId)await restore(String(route.query.recordId));else await importRoute();}catch(e){error.value=e.message;}});
onBeforeUnmount(()=>{disposed=true;actionSequence++;window.removeEventListener('erp:auth-scope-changed',resetScope);});
</script>
<template><main class="optimizer"><header><h2>AI优化</h2><div><el-button :disabled="Boolean(busy)" @click="importer.open('draft')">从草稿箱导入</el-button><el-button :disabled="Boolean(busy)" @click="importer.open('collector')">从采集箱导入</el-button><el-button @click="router.push('/ai-materials?source=optimization')">优化记录</el-button></div></header><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-empty v-if="!active" description="先导入需要优化的商品，保留原稿，逐项检查和改进"/><template v-else><el-select v-if="sources.length>1" :model-value="selected" :disabled="Boolean(busy)" @change="chooseSource"><el-option v-for="(s,i) in sources" :key="i" :value="i" :label="s.title+' · '+(s.sourceVariantKey||i+1)"/></el-select><section v-if="!active.templateId" class="template-choice"><h3>保存草稿的上架类目模板</h3><el-select filterable placeholder="选择本企业的上架模板" :disabled="Boolean(busy)" @change="bindTemplate"><el-option v-for="t in listingTemplates" :key="t.id" :value="t.id" :label="t.template_name||t.category_name||t.name"/></el-select></section><section class="analysis"><header><h3>整体分析</h3><el-button type="primary" :disabled="Boolean(busy)" :loading="busy==='analyze'" @click="analyze">一键分析</el-button></header><el-input v-model="manualAnalysis" :disabled="Boolean(busy)" type="textarea" :rows="3" placeholder="也可直接写下你的分析和改进方向，逐项优化无需先调用一键分析"/><div class="analysis-grid"><article v-for="s in analysisSections" :key="s.label"><strong>{{s.label}}</strong><p>{{s.value}}</p></article></div></section><section v-for="f in fields" :key="f.key" class="field"><h3>{{f.label}}</h3><div class="field-grid"><div class="comparison"><label>当前内容</label><el-image v-if="f.kind==='image'" :src="withImageToken(f.value)" fit="contain" :preview-src-list="[withImageToken(f.value)]"/><el-input v-else v-model="f.value" :disabled="Boolean(busy)" type="textarea" :rows="f.key==='description'?7:4"/><template v-if="f.result"><label>{{f.adopted && f.value===f.result?'已采用的新结果':'新结果 · 尚需确认采用'}}</label><el-image v-if="f.kind==='image'" :src="withImageToken(f.result)" fit="contain" :preview-src-list="[withImageToken(f.result)]"/><p v-else class="result">{{f.result}}</p><el-button :disabled="Boolean(busy)" type="success" @click="adopt(f)">采用这一项</el-button></template></div><div class="requirements"><el-select v-if="presets(f).length" clearable placeholder="选用我的提示词模板" :disabled="Boolean(busy)" @change="f.prompt=$event||''"><el-option v-for="p in presets(f)" :key="p.id" :value="p.payload.prompt" :label="p.name"/></el-select><el-input v-model="f.prompt" :disabled="Boolean(busy)" type="textarea" :rows="6" :placeholder="'填写'+f.label+'的优化要求'"/><template v-if="f.kind==='image'"><label class="upload">上传参考图<input type="file" accept="image/*" :disabled="Boolean(busy)" @change="uploadReference($event,f)"/></label><el-image v-if="f.reference" :src="withImageToken(f.reference)" class="reference" fit="contain"/><el-button v-if="f.reference" link :disabled="Boolean(busy)" @click="f.reference=''">移除参考图</el-button></template><el-button type="primary" :disabled="Boolean(busy)" :loading="busy===f.key" @click="optimize(f)">优化{{f.label}}</el-button></div></div></section><section class="scene-plan"><header><h3>从主图生成场景套图</h3></header><div class="plan-controls"><span>图片数量</span><el-input-number v-model="planCount" :disabled="Boolean(busy)" :min="1" :max="8"/><el-input v-model="planDirection" :disabled="Boolean(busy)" placeholder="期望场景与方向，例如材质特写、使用场景、包装内容"/><el-button :disabled="Boolean(busy)" :loading="busy==='plan'" @click="createPlan">先生成方案</el-button></div><article v-for="scene in plan||[]" :key="scene.id" class="scene"><el-input v-model="scene.name" :disabled="Boolean(busy)" @input="planConfirmed=false"/><el-input v-model="scene.prompt" :disabled="Boolean(busy)" type="textarea" :rows="3" @input="planConfirmed=false"/><el-alert v-if="scene.error" :title="scene.error" type="error"/><el-image v-if="scene.result" :src="withImageToken(scene.result)" fit="contain"/><el-button v-if="scene.result" :disabled="Boolean(busy)" @click="adoptScene(scene)">采用到详情图</el-button></article><div v-if="plan?.length" class="plan-controls"><el-checkbox v-model="planConfirmed" :disabled="Boolean(busy)">确认上述 {{plan.length}} 张图片的方向和数量</el-checkbox><el-button type="primary" :disabled="Boolean(busy)||!planConfirmed" :loading="busy==='scenes'" @click="generateScenes">生成／重试未完成图片</el-button></div></section><footer><span>生成结果会保存到记录；确认采用后可另存草稿。</span><el-button :disabled="Boolean(busy)" @click="work('save',persist)">保存当前记录</el-button><el-button type="primary" :disabled="Boolean(busy)||!hasResults||Boolean(draftId)" :loading="busy==='draft'" @click="saveDraft">另存到草稿箱</el-button><el-button v-if="draftId" @click="router.push('/listing-automation?draftId='+draftId)">打开新草稿</el-button></footer></template><AiProductImportDialog ref="importer" @import="importSource"/></main></template>
<style scoped>.optimizer{max-width:1500px;margin:auto;padding:20px}header,footer,.plan-controls{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}h2,h3{margin:0}section{padding:22px;border:1px solid var(--el-border-color);border-radius:10px;margin:20px 0;background:var(--el-bg-color)}header{margin-bottom:18px}.field-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,1fr);gap:30px;margin-top:18px}.comparison,.requirements{display:flex;flex-direction:column;gap:14px}.comparison>.el-image{width:100%;height:330px;background:var(--el-fill-color-light)}label,footer>span{font-size:13px;color:var(--el-text-color-secondary)}.result,p{white-space:pre-wrap;line-height:1.7}.result{padding:16px;background:var(--el-fill-color-light)}.reference{height:130px;width:130px}.analysis-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:18px;margin-top:18px}.plan-controls>.el-input{flex:1;min-width:200px}.scene{display:grid;gap:12px;margin-top:20px}.scene>.el-image{height:220px}.upload{display:flex;gap:12px;align-items:center}.upload input{max-width:240px}footer{padding:20px 0}@media(max-width:800px){.field-grid{grid-template-columns:1fr}.optimizer{padding:12px}.comparison>.el-image{height:260px}}
</style>
